WITH ship_mode_stats AS (SELECT cs.cs_bill_hdemo_sk AS hd_sk, sm.sm_ship_mode_id, COUNT(*) AS mode_cnt, ROW_NUMBER() OVER (PARTITION BY cs.cs_bill_hdemo_sk ORDER BY COUNT(*) DESC) AS rn FROM catalog_sales cs JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY cs.cs_bill_hdemo_sk, sm.sm_ship_mode_id), top_ship_mode AS (SELECT hd_sk, sm_ship_mode_id FROM ship_mode_stats WHERE rn = 1), cat_sales AS (SELECT cs.cs_bill_hdemo_sk AS hd_sk, SUM(cs.cs_quantity) AS cat_qty, SUM(cs.cs_net_paid) AS cat_net_paid FROM catalog_sales cs GROUP BY cs.cs_bill_hdemo_sk), store_sales_agg AS (SELECT ss.ss_hdemo_sk AS hd_sk, SUM(ss.ss_quantity) AS store_qty, SUM(ss.ss_net_paid) AS store_net_paid FROM store_sales ss GROUP BY ss.ss_hdemo_sk) SELECT hd.hd_demo_sk, hd.hd_buy_potential, ts.sm_ship_mode_id AS top_ship_mode, COALESCE(cs.cat_qty, 0) AS cat_quantity, COALESCE(ss.store_qty, 0) AS store_quantity, (COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)) AS total_quantity, (COALESCE(cs.cat_qty, 0) * 100.0) / NULLIF((COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)), 0) AS cat_qty_pct, (COALESCE(ss.store_qty, 0) * 100.0) / NULLIF((COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)), 0) AS store_qty_pct, CASE WHEN (COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)) > 1000 THEN 'HIGH_VOLUME' WHEN (COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)) BETWEEN 500 AND 1000 THEN 'MEDIUM_VOLUME' ELSE 'LOW_VOLUME' END AS volume_category, RANK() OVER (ORDER BY (COALESCE(cs.cat_qty, 0) + COALESCE(ss.store_qty, 0)) DESC) AS quantity_rank FROM household_demographics hd LEFT JOIN cat_sales cs ON hd.hd_demo_sk = cs.hd_sk LEFT JOIN store_sales_agg ss ON hd.hd_demo_sk = ss.hd_sk LEFT JOIN top_ship_mode ts ON hd.hd_demo_sk = ts.hd_sk WHERE hd.hd_buy_potential IS NOT NULL ORDER BY quantity_rank LIMIT 20
